export const BODY: string = "\n<p>كل لون على شاشتك له عدة أسماء. نفس الأزرق قد يكون #2563EB أو rgb(37, 99, 235) أو hsl(221, 83%, 53%)، والثلاثة تصف البكسلات نفسها بالضبط.</p>\n<p>هذا التداخل يربك المبتدئين. فإذا كانت الأكواد قابلة للتبادل، فلماذا توجد أربع صيغ وأيها يجب أن تستخدم فعلًا؟</p>\n<p>يشرح هذا المقال HEX وRGB وHSL وCMYK جنبًا إلى جنب: ماذا تعني كل منها وأين تُستخدم وكيف تختار الصيغة المناسبة لعملك.</p>\n<h2 id=\"why-multiple-formats-exist\">لماذا توجد صيغ ألوان عدة؟</h2>\n<p>كل عمل يحتاج وصفًا مختلفًا للون. مطور الويب يريد كودًا قصيرًا للصقه في CSS، بينما المصمم يريد وصف لون كدرجة بإضاءة وتشبع.</p>\n<p>وُلد HEX من طريقة حفظ الحواسيب للون: ثلاثة بايتات، واحد للأحمر وواحد للأخضر وواحد للأزرق، مكتوبة كستة أرقام ست عشرية. إنه مضغوط وسهل النسخ. ووُلد RGB من طريقة إنتاج الشاشات للون: ثلاثة أضواء حمراء وخضراء وزرقاء، كل منها بشدة من 0 إلى 255.</p>\n<h2 id=\"hex-explained\">HEX مشروح</h2>\n<p>كود HEX يبدأ بعلامة المربع متبوعة بستة أرقام ست عشرية، مثل #2563EB. أول رقمين للأحمر، والاثنان التاليان للأخضر، والاثنان الأخيران للأزرق.</p>\n<p>كل زوج يتراوح من 00 إلى FF بالنظام الست عشري، ما يعادل 0 إلى 255 بالنظام العشري. وهكذا #FF0000 أحمر نقي و#00FF00 أخضر نقي و#000000 أسود. وHEX هو الصيغة الافتراضية لـCSS ومعظم أدوات التصميم: قصير ويُلصق دون مشكلة في ورقة أنماط.</p>\n<h2 id=\"rgb-explained\">RGB مشروح</h2>\n<p>يكتب RGB القيم الثلاث نفسها كأرقام عشرية، مثل rgb(37, 99, 235). كل رقم يتراوح من 0، أي لا ضوء من ذلك اللون، إلى 255، أي الشدة الكاملة.</p>\n<p>RGB هو الوصف الأكثر حرفية لما تفعله الشاشة. يقول بالضبط كم ضوء أحمر وأخضر وأزرق يجب خلطه، ولهذا تستخدمه محررات الصور والكاميرات داخليًا. كما يدعم RGB الشفافية عبر RGBA، الذي يضيف رقمًا رابعًا للعتامة: rgba(37, 99, 235, 0.5) هو نفس الأزرق بنصف عتامة.</p>\n<h2 id=\"hsl-explained\">HSL مشروح</h2>\n<p>يصف HSL اللون بثلاث أفكار مختلفة: الدرجة والتشبع والإضاءة. وقيمة نموذجية تبدو هكذا: hsl(221, 83%, 53%).</p>\n<p>الدرجة زاوية على عجلة الألوان، من 0 إلى 360 درجة. الأحمر قرب 0، والأخضر قرب 120، والأزرق قرب 240، وتعود العجلة إلى الأحمر عند 360. والتشبع نسبة مئوية: 0 بالمئة رمادي و100 بالمئة أشد نسخة حية من الدرجة. والإضاءة نسبة مئوية أيضًا: 0 أسود و50 الدرجة النقية و100 أبيض.</p>\n<h2 id=\"cmyk-explained\">CMYK مشروح</h2>\n<p>يصف CMYK اللون كحبر على ورق: سماوي وأرجواني وأصفر وأسود، كل منها كنسبة مئوية. وقيمة نموذجية هي cmyk(84%, 58%, 0%, 8%).</p>\n<p>الطابعات تخلط الأحبار بشكل طرحي، عكس الشاشات. بينما تضيف الشاشة ضوءًا للوصول إلى الأبيض، تبدأ الطابعة من ورق أبيض وتضيف حبرًا للوصول إلى الداكن. وهذا الفرق يعني أن بعض ألوان الشاشة لا يمكن طباعتها بدقة: الأزرق والأخضر الساطعان جدًا يقعان غالبًا خارج نطاق الأحبار.</p>\n<h2 id=\"hex-vs-rgb\">HEX مقابل RGB: أيهما تستخدم؟</h2>\n<p>يصف HEX وRGB اللون نفسه بنفس الأرقام الثلاثة، مكتوبة فقط بطريقة أخرى. #2563EB وrgb(37, 99, 235) هما نفس الأزرق في تدوينين.</p>\n<p>اختر HEX لـCSS وللمشاركة. إنه أقصر، وهو العرف في أوراق الأنماط، ويُنسخ دون مشكلة في أدوات التصميم ورسائل المحادثة. واختر RGB عندما تطلب منك أداة ثلاثة أرقام أو عندما تحتاج شفافية، فـRGBA هي الطريقة القياسية لكتابة لون شبه شفاف في CSS.</p>\n<h2 id=\"hsl-vs-hex-rgb\">HSL مقابل HEX وRGB: متى يفوز HSL</h2>\n<p>يفوز HSL عندما تصمم نظام ألوان بدل تسمية لون واحد. اللوحة المبنية في HSL تبقى متماسكة لأن الدرجة تبقى ثابتة بينما تتغير الإضاءة.</p>\n<p>فكر في زر بثلاث حالات: عادي وعند التحويم ومعطل. في HSL تحافظ على الدرجة 221 والتشبع 83 بالمئة، ثم تضع الإضاءة على 53 و45 و70 بالمئة. وفعل الشيء نفسه في HEX يعني اختراع ثلاثة أكواد لا علاقة بينها، وقد تبدو جيدة لكن لا شيء في الأكواد يقول إنها تنتمي معًا.</p>\n<h2 id=\"converting-between-formats\">كيف تحوّل بين الصيغ</h2>\n<p>نادرًا ما تحتاج إلى التحويل يدويًا، لأن منتقي الألوان يعرض كل الصيغ دفعة واحدة. ومع ذلك، فهم التحويل يساعدك على الثقة بالأرقام.</p>\n<p>من HEX إلى RGB تحويل قاعدة: كل زوج من الأرقام الست عشرية يتحول إلى عشري من 0 إلى 255. FF هي 255 و80 هي 128 و00 هي 0. ومن RGB إلى HSL صيغة لا جدول: تجد الأكبر والأصغر من القيم الثلاث، وتشتق الإضاءة من متوسطهما، وتحسب الدرجة حسب أي قناة هي الأكبر.</p>\n<h2 id=\"which-format-for-web\">أي صيغة تستخدم على الويب؟</h2>\n<p>لمعظم مواقع الويب، HEX هو الخيار الآمن الافتراضي. إنه قصير ومدعوم عالميًا وكل مطور يتعرف عليه بنظرة واحدة.</p>\n<p>استخدم RGBA عندما تحتاج شفافية. طبقة شبه شفافة أو ظل ناعم أبسط كـrgba بقيمة عتامة أقل من 1. واستخدم HSL عندما تبني سمة بدرجات منهجية. أنظمة التصميم التي تولد متغيرات فاتحة وداكنة من درجة واحدة أسهل بكثير في الصيانة في HSL.</p>\n<h2 id=\"which-format-for-print\">أي صيغة تستخدم للطباعة؟</h2>\n<p>للطباعة، CMYK هي لغة العمل. المطابع تفكر بنسب الحبر، والملف المُعد بـCMYK يتجنب المفاجآت على المطبعة.</p>\n<p>ابدأ من لون الشاشة، وسجل تقريب CMYK من المنتقي، ثم أكده بطبعة تجريبية. الطبعة التجريبية هي الفحص الحقيقي الوحيد. ولا ترسل أبدًا عمل طباعة بكود HEX وحده دون الحديث عن CMYK، فالمطبعة ستحوّله، لكن التحويل قد يختار قيم حبر لم تكن لتختارها.</p>\n<h2 id=\"which-format-for-design-tools\">أي صيغة تستخدم في أدوات التصميم؟</h2>\n<p>فيغما وفوتوشوب وكانفا تقبل HEX الملصوق في حقول الألوان، فـHEX هي أسرع طريقة لنقل لون مختار إلى تصميم.</p>\n<p>وعندما تضبط لونًا داخل الأداة، ستسحب غالبًا أشرطة تمرير بأسلوب HSL للدرجة والتشبع والإضاءة. والأداة تعرض HEX، لكنك تفكر في HSL. وأدلة العلامات التجارية تسرد الثلاثة عادة: HEX للمطورين وRGB للمستندات وCMYK للطباعة. وهذه ممارسة جيدة، لأن كل جمهور يستخدم صيغة مختلفة.</p>\n<h2 id=\"common-mistakes\">الأخطاء الشائعة مع صيغ الألوان</h2>\n<p>الخطأ الأكثر شيوعًا هو افتراض أن HEX وRGB لونان مختلفان. إنهما طريقتان لكتابة القيمة نفسها، فـ#2563EB وrgb(37, 99, 235) ستتطابقان دائمًا.</p>\n<p>من الأخطاء الأخرى معاملة تقريب CMYK كأنه دقيق. التحويل من شاشة إلى طباعة صيغة، واللون المطبوع الحقيقي يعتمد على المطبعة والحبر والورق. والناس ينسون أيضًا أن الإضاءة ليست السطوع: في HSL، رفع الإضاءة نحو 100 بالمئة يغسل اللون نحو الأبيض، بينما خفضها نحو 0 يدفعه نحو الأسود.</p>\n<h2 id=\"reading-a-color-picker-output\">كيف تقرأ مخرجات منتقي الألوان</h2>\n<p>عندما تأخذ عينة من بكسل، يعرض المنتقي كل الصيغ دفعة واحدة. كود HEX هو الذي تنسخه لعمل الويب، وأرقام RGB هي التي تنسخها للمستندات.</p>\n<p>قيم HSL تخبرك أين يقع اللون على العجلة ومدى حيويته. درجة قرب 0 أو 360 حمراء، وقرب 120 خضراء، وقرب 240 زرقاء. ونسب CMYK تخبرك كم حبر سيحتاجه اللون. ولون فيه كثير من السماوي والأرجواني ولا أصفر هو أزرق، بينما كثير من الأصفر مع بعض الأرجواني برتقالي.</p>\n<h2 id=\"building-a-palette-with-formats\">كيف تبني لوحة بصيغ عدة</h2>\n<p>اللوحة الجيدة تبقي صيغة واحدة مصدر حقيقة وتشتق البقية. معظم الفرق تبقي HEX مصدرًا، لأنها الصيغة التي يلصقها المطورون في الكود.</p>\n<p>ومن قاعدة HEX، ولّد متغيرات أفتح وأظلم في HSL بتغيير الإضاءة فقط. وهذا يبقي عائلة الدرجات سليمة واللوحة متماسكة. وسجل قيم RGB للمستندات وتقريبات CMYK للطباعة. ودليل علامة بأربع صيغ يخدم كل الفرق دون أن يحوّل أحد أثناء العمل.</p>\n<h2 id=\"hsl-and-accessibility\">HSL وسهولة الوصول: التباين حسب الإضاءة</h2>\n<p>قواعد سهولة الوصول تهتم بالتباين، وHSL يجعل التباين سهل التفكير فيه. لونان بقيم إضاءة متباعدة جدًا يمران عادة في فحص التباين، بينما لونان بإضاءة متشابهة لا يمران بغض النظر عن درجتيهما.</p>\n<p>فكر في نص داكن فوق خلفية فاتحة. إذا كان النص بإضاءة قرب 15 بالمئة والخلفية قرب 95 بالمئة، فالفجوة كبيرة وسيكون النص سهل القراءة لمعظم الناس. وينطبق المنطق نفسه عكسيًا للوضع الداكن: نص فاتح بإضاءة 90 بالمئة فوق خلفية داكنة 10 بالمئة يعطي نفس الفجوة الكبيرة.</p>\n<h2 id=\"quick-reference\">مرجع سريع: ورقة غش للصيغ</h2>\n<p>HEX ستة أرقام بعد علامة مربع، مثل #2563EB. استخدمه في CSS وفي أدوات التصميم وكلما شاركت لونًا كتابة.</p>\n<p>RGB ثلاثة أرقام من 0 إلى 255، مثل rgb(37, 99, 235). استخدمه في المستندات وبرامج المكتب وعندما تحتاج شفافية عبر RGBA. وHSL زاوية درجة مع نسبتي تشبع وإضاءة، مثل hsl(221, 83%, 53%). استخدمه عند بناء درجات وظلال ومتغيرات سمة.</p>\n<p>CMYK أربعة نسب حبر للطباعة. استخدمه كتقريب أولي للعمل المطبوع وأكده دائمًا بطبعة تجريبية. وللجزء العملي، جرّب <a href=\"/ar/muntqi-alwan-as-sura/\">منتقي لون الصورة</a> و<a href=\"/ar/istikraj-lauhat-alwan-min-as-sura/\">مستخرج لوحة ألوان الصورة</a>. وللسياق، اقرأ <a href=\"/ar/blog/kayfiyya-ikhtiyar-lawn-min-as-sura/\">كيف تختار لونًا من صورة</a> و<a href=\"/ar/blog/dalil-muntqi-alwan-as-suwar/\">منتقي لون الصورة: الدليل الكامل</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"HEX أم RGB أفضل لألوان موقع ويب؟","answer":"لا أحدهما أفضل في اللون نفسه، لأنهما يصفان القيمة نفسها. HEX أقصر وهو العرف في أوراق الأنماط، فمعظم المطورين يفضله. وRGB أفضل عندما تحتاج شفافية، لأن RGBA هي الطريقة القياسية لكتابة لون شبه شفاف."},{"question":"لماذا يبدو لون علامتي مختلفًا في الطباعة عنه على الشاشة؟","answer":"الشاشات تنشئ اللون بالضوء والطابعات تنشئه بالحبر، والنظامان يغطيان نطاقات مختلفة. الأزرق والأخضر الساطعان على الشاشة يقعان غالبًا خارج ما تستطيع الأحبار إعادة إنتاجه، فتبدو الطبعة باهتة أو مختلفة."},{"question":"هل يمكنني تحويل كود HEX إلى HSL دون أداة؟","answer":"نعم، لكنه يستغرق خطوتين: حوّل HEX إلى RGB أولًا ثم طبق صيغة RGB إلى HSL. المنتقي يقوم بالخطوتين فورًا ويعرض كل الصيغ دفعة واحدة. ولتحويلات مفردة، أي محول ألوان عبر الإنترنت يعمل."},{"question":"ماذا يعني رقم الدرجة في HSL فعلًا؟","answer":"الدرجة زاوية من 0 إلى 360 درجة على عجلة الألوان. الأحمر قرب 0 والأصفر قرب 60 والأخضر قرب 120 والسماوي قرب 180 والأزرق قرب 240 والأرجواني قرب 300. ولونان بدرجتين متقابلتين مكملان."},{"question":"هل أحتاج إلى قيم CMYK لموقع ويب أو رسم اجتماعي؟","answer":"لا، فمواقع الويب والتطبيقات والرسوم الاجتماعية وسائط شاشة، فـHEX أو RGB أو HSL تكفي. CMYK يهم فقط عندما يلمس الحبر الورق. واحفظ تقريب CMYK تحسبًا لاستخدام لون العلامة نفسه في الطباعة يومًا ما."},{"question":"لماذا بعض أكواد HEX بثلاثة أرقام فقط؟","answer":"كود HEX بثلاثة أرقام هو الصيغة المختصرة لكود من ستة أرقام يكون فيه كل زوج رقمين متطابقين. #369 تعني #336699، لأن 3 تتضاعف إلى 33 و6 إلى 66 و9 إلى 99. ولا يمكن اختصار كل كود، فقط تلك التي تتطابق أزواجها."}];
